UPDATE `{{prefix}}settings` SET setting_value='Αγαπητέ/ή κηδεμόνα,\n\nΣας ενημερώνουμε για τις παρακάτω απουσίες {student_title_gen} {student_genitive}:\n\nΗμερομηνία: {date}\nΏρες απουσίας: {hours}\n\nΓια οποιαδήποτε διευκρίνιση, μπορείτε να επικοινωνήσετε με το σχολείο.\n\nΜε εκτίμηση,\nΗ Διεύθυνση\n{school_name}\nΤηλ.: {school_phone}'
WHERE setting_key='email_template_body' AND setting_value='Αγαπητέ κηδεμόνα {guardian_name_voc},\n\nΣας ενημερώνουμε ότι {student_title} {student_full_name} σημείωσε σήμερα {date} απουσία κατά τις εξής διδακτικές ώρες: {hours}.\n\nΜε εκτίμηση,\nΗ Διεύθυνση του {school_name}\nΤηλ: {school_phone}';
